<?php
require_once __DIR__.'/config/db.php';require_once __DIR__.'/config/auth.php';require_login();
$pageTitle='Messaggi';$active='messaggi';$id=$_SESSION['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){$to=(int)($_POST['destinatario_id']??0);$oggetto=trim($_POST['oggetto']??'');$corpo=trim($_POST['corpo']??'');if($to&&$oggetto){$stmt=$pdo->prepare('INSERT INTO messaggi(mittente_id,destinatario_id,oggetto,corpo) VALUES(?,?,?,?)');$stmt->execute([$id,$to,$oggetto,$corpo]);flash('success','Messaggio inviato correttamente.');}header('Location: messaggi.php');exit;}
if(isset($_GET['leggi'])){$stmt=$pdo->prepare('UPDATE messaggi SET letto=1 WHERE id=? AND destinatario_id=?');$stmt->execute([(int)$_GET['leggi'],$id]);}
$stmt=$pdo->prepare('SELECT me.id,me.oggetto,me.corpo,me.letto,me.created_at,u.nome mittente FROM messaggi me LEFT JOIN utenti u ON u.id=me.mittente_id WHERE me.destinatario_id=? ORDER BY me.created_at DESC');$stmt->execute([$id]);$inbox=$stmt->fetchAll();
$stmt=$pdo->prepare('SELECT id,nome,ruolo FROM utenti WHERE id<>? ORDER BY nome');$stmt->execute([$id]);$destinatari=$stmt->fetchAll();$success=flash('success');
require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><main class="main"><header class="topbar"><h1>Messaggi</h1><div class="user-menu"><a href="logout.php">Esci</a></div></header><section class="content"><div class="page-head"><h2>Comunicazioni</h2><p>Leggi e invia messaggi interni alla piattaforma.</p></div><?php if($success): ?><div class="flash success"><?=e($success)?></div><?php endif?><div class="grid"><div class="card"><h3>Nuovo messaggio</h3><form method="post"><div class="field"><label>Destinatario</label><select name="destinatario_id" required><option value="">Seleziona</option><?php foreach($destinatari as $d): ?><option value="<?=$d['id']?>"><?=e($d['nome'])?> · <?=e($d['ruolo'])?></option><?php endforeach?></select></div><div class="field"><label>Oggetto</label><input name="oggetto" required maxlength="150"></div><div class="field"><label>Testo</label><textarea name="corpo" rows="4"></textarea></div><button class="btn">Invia messaggio</button></form></div><div class="card"><h3>Posta in arrivo</h3><?php if(!$inbox): ?><p class="empty">Nessun messaggio ricevuto.</p><?php endif;foreach($inbox as $m): ?><div class="msg"><strong><?=e($m['oggetto'])?><?php if(!$m['letto']): ?><span class="badge">Nuovo</span><?php endif?></strong><div class="meta">Da <?=e($m['mittente']??'Segreteria')?> · <?=date('d/m/Y H:i',strtotime($m['created_at']))?></div><p class="muted"><?=e($m['corpo']??'')?></p><?php if(!$m['letto']): ?><a class="muted" href="?leggi=<?=$m['id']?>">Segna come letto</a><?php endif?></div><?php endforeach?></div></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>